(window.QBANK = window.QBANK || []).push(
  {"id": "jm26-0121s2-01", "exam": "JEE", "subject": "Chemistry", "chapter": "Aldehydes & Ketones", "type": "mcq", "difficulty": 2, "q": "Match List - I with List - II.\nList – I\nReagents\nA. H₂, Pd–BaSO₄\nB. SnCl₂, HCl\nC. CrO₂Cl₂, CS₂\nD. CO, HCl, Anhyd. AlCl₃\nList – II\nReaction Name (Involving aldehydes)\nI. Etard Reaction\nII. Rosenmund Reduction\nIII. Gattermann–Koch Reaction\nIV. Stephen Reaction\nChoose the correct answer from the options given below :", "options": ["A-II, B-III, C-IV, D-I", "A-IV, B-III, C-I, D-II", "A-IV, B-I, C-II, D-III", "A-II, B-IV, C-I, D-III"], "answer": 3, "hint": "Recall which named reaction makes aldehydes from acid chlorides, nitriles, toluene and benzene.", "solution": "H₂/Pd–BaSO₄ reduces RCOCl (Rosenmund); SnCl₂/HCl reduces nitriles (Stephen); CrO₂Cl₂ oxidises toluene (Etard); CO/HCl/AlCl₃ formylates benzene (Gattermann–Koch).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-02", "exam": "JEE", "subject": "Chemistry", "chapter": "p-Block Elements", "type": "mcq", "difficulty": 1, "q": "On heating a mixture of common salt and $K_2Cr_2O_7$ in equal amount along with concentrated $H_2SO_4$ in a test tube, a gas is evolved. Formula of the gas evolved and oxidation state of the central metal atom in the gas respectively are:", "options": ["$Cr_2O_2Cl_2$ and +3", "$Cr_2O_2Cl_2$ and +6", "$CrO_2Cl_2$ and +6", "$CrO_2Cl_2$ and +5"], "answer": 2, "hint": "This is the chromyl chloride test for Cl⁻.", "solution": "Chloride + K₂Cr₂O₇ + conc. H₂SO₄ gives red vapours of CrO₂Cl₂, in which Cr is +6.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-03", "exam": "JEE", "subject": "Chemistry", "chapter": "Biomolecules", "type": "mcq", "difficulty": 2, "q": "The correct statements are :\nA. Activation energy for enzyme catalysed hydrolysis of sucrose is lower than that of acid catalysed hydrolysis.\nB. During denaturation, secondary and tertiary structures of a protein are destroyed but primary structure remains intact.\nC. Nucleotides are joined together by glycosidic linkage between $\\mathrm{C}_1$ and $\\mathrm{C}_4$ carbons of the pentose sugar.\nD. Quaternary structure of proteins represents overall folding of the polypeptide chain.\nChoose the correct answer from the options given below :", "options": ["A, B and D Only", "A, C and D Only", "B and C Only", "A and B Only"], "answer": 3, "hint": "Check each statement: linkage in nucleic acids, and the levels of protein structure.", "solution": "A and B are true. Nucleotides are joined by phosphodiester links (C5′–C3′), not glycosidic ones. Overall folding of a chain is the tertiary structure, not quaternary.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-04", "exam": "JEE", "subject": "Chemistry", "chapter": "General Organic Chemistry", "type": "mcq", "difficulty": 3, "q": "Statement I : Compound (X), shown below, dissolves in NaHCO₃ solution and has two chiral carbon atoms\nStatement II : Compound (Y), shown below, has two carbons with sp³ hybridization, one carbon with sp² and one carbon with sp hybridization\nIn the light of the above statements, choose the correct answer from the options given below :", "img": "figures/pyq/jm26-0121s2-04.png", "imgAlt": "Structures of compound X (keto acid on cyclopentane) and Y (ethylketene)", "options": ["Statement I is true but Statement II is false", "Both Statement I and Statement II are true", "Both Statement I and Statement II are false", "Statement I is false but Statement II is true"], "answer": 1, "hint": "X has a free –COOH; count its stereocentres. For Y, assign CH₃, CH₂, CH= and =C= carbons.", "solution": "X: –COOH reacts with NaHCO₃; the two ring carbons carrying COOH and the aroyl group are chiral. Y (CH₃CH₂CH=C=O): two sp³, one sp² and one sp (ketene) carbon. Both true.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-05", "exam": "JEE", "subject": "Chemistry", "chapter": "d & f Block Elements", "type": "mcq", "difficulty": 2, "q": "Given below are some of the statements about Mn and $\\mathrm{Mn}_2\\mathrm{O}_7$. Identify the correct statements.\nA. Mn forms the oxide $\\mathrm{Mn}_2\\mathrm{O}_7$, in which Mn is in its highest oxidation state.\nB. Oxygen stabilizes the Mn in higher oxidation states by forming multiple bonds with Mn.\nC. $\\mathrm{Mn}_2\\mathrm{O}_7$ is an ionic oxide.\nD. The structure of $\\mathrm{Mn}_2\\mathrm{O}_7$ consists of one bridged oxygen.\nChoose the correct answer from the options given below :", "options": ["A, B, C and D", "A, B and D Only", "A, B and C Only", "A, C and D Only"], "answer": 1, "hint": "Mn₂O₇ is a covalent green oil.", "solution": "A: Mn is +7. B: Mn=O multiple bonds stabilise high oxidation states. D: O₃Mn–O–MnO₃ has one bridging O. C is false because Mn₂O₇ is covalent.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-06", "exam": "JEE", "subject": "Chemistry", "chapter": "Amines", "type": "mcq", "difficulty": 3, "q": "Consider the above sequence of reactions. The number of bromine atom(s) in the final product (P) will be :", "img": "figures/pyq/jm26-0121s2-06.png", "imgAlt": "Six-step reaction sequence starting from nitrobenzene", "options": ["6", "5", "1", "3"], "answer": 1, "hint": "Track the directing effects: NO₂ is meta-directing, and after reduction NH₂ activates o/p.", "solution": "m-bromonitrobenzene, then m-bromoaniline. Br₂/H₂O brominates the three o/p positions to give 2,3,4,6-tetrabromoaniline. Sandmeyer (CuBr) replaces NH₂ with Br, giving pentabromobenzene: 5 Br.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-07", "exam": "JEE", "subject": "Chemistry", "chapter": "General Organic Chemistry", "type": "mcq", "difficulty": 1, "q": "Match List - I with List - II.\nList - I Pair of Compounds\nA. 2-Methylpropene and but-1-ene\nB. Cis-but-2-ene and trans-but-2-ene\nC. 2-Butanol and diethyl ether\nD. But-1-ene and but-2-ene\nList - II Type of Isomers\nI. Stereoisomers\nII. Position isomers\nIII. Chain isomers\nIV. Functional group isomers\nChoose the correct answer from the options given below :", "options": ["A-III, B-I, C-IV, D-II", "A-II, B-I, C-IV, D-III", "A-I, B-IV, C-III, D-II", "A-III, B-I, C-II, D-IV"], "answer": 0, "hint": "Chain vs position vs functional vs stereo.", "solution": "A: branched vs straight chain, so chain isomers. B: cis/trans, so stereoisomers. C: alcohol vs ether, so functional isomers. D: double-bond position, so position isomers.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-08", "exam": "JEE", "subject": "Chemistry", "chapter": "Chemical Bonding", "type": "mcq", "difficulty": 2, "q": "The correct increasing order of C–H(A), C–O(B), C=O(C) and C≡N(D) bonds in terms of covalent bond length is :", "options": ["D < C < B < A", "D < C < A < B", "A < B < C < D", "A < D < C < B"], "answer": 3, "hint": "Typical lengths: C–H ≈ 109, C≡N ≈ 116, C=O ≈ 122, C–O ≈ 143 pm.", "solution": "C–H < C≡N < C=O < C–O, i.e. A < D < C < B.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-09", "exam": "JEE", "subject": "Chemistry", "chapter": "Periodic Properties", "type": "mcq", "difficulty": 2, "q": "Given below are two statements :\nStatement I : The correct order in terms of atomic/ionic radii is Al > Mg > Mg²⁺ > Al³⁺.\nStatement II : The correct order in terms of the magnitude of electron gain enthalpy is Cl > Br > S > O.\nIn the light of the above statements, choose the correct answer from the options given below :", "options": ["Statement I is true but Statement II is false", "Both Statement I and Statement II are true", "Statement I is false but Statement II is true", "Both Statement I and Statement II are false"], "answer": 2, "hint": "Compare r(Mg) and r(Al), then recall the O and F anomalies in electron gain enthalpy.", "solution": "I is false: Mg (160 pm) is larger than Al (143 pm). II is true: |Δ_eg H| Cl 349 > Br 325 > S 200 > O 141 kJ/mol.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-10", "exam": "JEE", "subject": "Chemistry", "chapter": "Electrochemistry", "type": "mcq", "difficulty": 1, "q": "For a closed circuit Daniell cell, which of the following plots is the accurate one at a given temperature?", "options": [{"img": "figures/pyq/jm26-0121s2-10-oa.png", "alt": "E° rising linearly with time"}, {"img": "figures/pyq/jm26-0121s2-10-ob.png", "alt": "E° falling linearly with time"}, {"img": "figures/pyq/jm26-0121s2-10-oc.png", "alt": "E° vertical line at a later time"}, {"img": "figures/pyq/jm26-0121s2-10-od.png", "alt": "E° horizontal line (constant)"}], "answer": 3, "hint": "E° is a standard-state constant; only E_cell changes as the cell runs.", "solution": "The standard cell potential does not depend on time, so the plot is a horizontal line.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-11", "exam": "JEE", "subject": "Chemistry", "chapter": "Thermodynamics", "type": "mcq", "difficulty": 2, "q": "Consider the following data :\n$\\Delta_fH^{\\circ}$ (methane, g) = $-X\\ \\text{kJ mol}^{-1}$\nEnthalpy of sublimation of graphite = $Y\\ \\text{kJ mol}^{-1}$\nDissociation enthalpy of $H_2=Z\\ \\text{kJ mol}^{-1}$\nThe bond enthalpy of C–H bond is given by :", "options": ["$\\frac{X+Y+2Z}{4}$", "$\\frac{X+Y+4Z}{2}$", "$\\frac{-X+Y+Z}{4}$", "$X+Y+Z$"], "answer": 0, "hint": "Build CH₄(g) → C(g) + 4H(g) from the given steps.", "solution": "4ε(C–H) = −Δ_fH(CH₄) + ΔH_sub(C) + 2ΔH_diss(H₂) = X + Y + 2Z, so ε = (X + Y + 2Z)/4.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-12", "exam": "JEE", "subject": "Chemistry", "chapter": "Haloalkanes & Haloarenes", "type": "mcq", "difficulty": 2, "q": "The correct order of the rate of the reaction for the following reaction with respect to nucleophiles is :\n$CH_3Br+Nu^-\\longrightarrow CH_3Nu+Br^-$", "options": ["$ClO_4^-\\gt CH_3COO^-\\gt OH^-\\gt PhO^-$", "$OH^-\\gt PhO^-\\gt CH_3COO^-\\gt ClO_4^-$", "$CH_3COO^-\\gt PhO^-\\gt OH^-\\gt ClO_4^-$", "$PhO^-\\gt OH^-\\gt CH_3COO^-\\gt ClO_4^-$"], "answer": 1, "hint": "S_N2 rate follows nucleophilicity; a more delocalised charge means a weaker nucleophile.", "solution": "OH⁻ > PhO⁻ (charge delocalised into the ring) > CH₃COO⁻ (over two O) > ClO₄⁻ (over four O).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-13", "exam": "JEE", "subject": "Chemistry", "chapter": "Organic Analysis", "type": "mcq", "difficulty": 2, "q": "By usual analysis, 1.00 g of compound (X) gave 1.79 g of magnesium pyrophosphate. The percentage of phosphorus in compound (X) is : (nearest integer)\n(Given, molar mass in g mol⁻¹: O = 16, Mg = 24, P = 31)", "options": ["40", "30", "20", "50"], "answer": 3, "hint": "Mg₂P₂O₇ (M = 222) contains 62 g of P per mole.", "solution": "P = 1.79 × 62/222 = 0.50 g in 1.00 g, so 50%.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-14", "exam": "JEE", "subject": "Chemistry", "chapter": "Coordination Compounds", "type": "mcq", "difficulty": 3, "q": "Given below are two statements :\nStatement I : Crystal Field Stabilization Energy (CFSE) of [Cr(H₂O)₆]²⁺ is greater than that of [Mn(H₂O)₆]²⁺.\nStatement II : Potassium ferricyanide has a greater spin-only magnetic moment than sodium ferrocyanide.\nIn the light of the above statements, choose the correct answer from the options given below :", "options": ["Statement I is true but Statement II is false", "Both Statement I and Statement II are true", "Both Statement I and Statement II are false", "Statement I is false but Statement II is true"], "answer": 1, "hint": "Cr²⁺ is d⁴ high spin, Mn²⁺ is d⁵ high spin; the cyanides are low spin.", "solution": "CFSE: d⁴ HS = −0.6Δ₀ vs d⁵ HS = 0, so I is true. K₃[Fe(CN)₆]: Fe³⁺ LS d⁵ has 1 unpaired e (1.73 BM); Na₄[Fe(CN)₆]: Fe²⁺ LS d⁶ has 0. II is true.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-15", "exam": "JEE", "subject": "Chemistry", "chapter": "p-Block Elements", "type": "mcq", "difficulty": 2, "q": "Given below are two statements :\nStatement I : The correct order in terms of bond dissociation enthalpy is Cl₂ > Br₂ > F₂ > I₂.\nStatement II : The correct trend in the covalent character of the metal halides is [SnCl₄ > SnCl₂], [PbCl₄ > PbCl₂] and [UF₄ > UF₆].\nIn the light of the above statements, choose the correct answer from the options given below :", "options": ["Both Statement I and Statement II are true", "Both Statement I and Statement II are false", "Statement I is false but Statement II is true", "Statement I is true but Statement II is false"], "answer": 3, "hint": "F₂ is anomalously weak. A higher oxidation state gives more covalent character.", "solution": "I: Cl₂ 242 > Br₂ 193 > F₂ 158 > I₂ 151 kJ/mol, true. II: UF₆ is more covalent than UF₄, so II is false.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-16", "exam": "JEE", "subject": "Chemistry", "chapter": "Chemical Kinetics", "type": "mcq", "difficulty": 1, "q": "Decomposition of A is a first order reaction at T(K) and is given by A(g) → B(g) + C(g).\nIn a closed 1 L vessel, 1 bar A(g) is allowed to decompose at T(K). After 100 minutes, the total pressure was 1.5 bar. What is the rate constant (in min⁻¹) of the reaction? (log 2 = 0.3)", "options": ["$6.9\\times {10}^{-4}$", "$6.9\\times {10}^{-3}$", "$6.9\\times {10}^{-1}$", "$6.9\\times {10}^{-2}$"], "answer": 1, "hint": "P_total = 1 + x.", "solution": "x = 0.5 bar after 100 min, so that is one half-life: k = 0.693/100 = 6.9 × 10⁻³ min⁻¹.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-17", "exam": "JEE", "subject": "Chemistry", "chapter": "General Organic Chemistry", "type": "mcq", "difficulty": 1, "q": "Given below are four compounds :\n(a) n-propyl chloride (b) iso-propyl chloride\n(c) sec-butyl chloride (d) neo-pentyl chloride\nPercentage of carbon in the one which exhibits optical isomerism is :", "options": ["46", "40", "52", "56"], "answer": 2, "hint": "Only a compound with a stereocentre is optically active.", "solution": "sec-Butyl chloride, C₄H₉Cl (M = 92.5): %C = 48/92.5 ≈ 52.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-18", "exam": "JEE", "subject": "Chemistry", "chapter": "Haloalkanes & Haloarenes", "type": "mcq", "difficulty": 3, "q": "The correct order of reactivity of the following benzyl halides towards reaction with KCN is :", "img": "figures/pyq/jm26-0121s2-18.png", "imgAlt": "Four para/meta-substituted benzyl bromides a–d", "options": ["a > b > c > d", "b > a > d > c", "b > a > c > d", "a > b > d > c"], "answer": 1, "hint": "Electron donors stabilise the benzylic transition state or cation. p-NO₂ withdraws more strongly than m-NO₂ (resonance).", "solution": "–NH₂ > –OH (donors), then m-NO₂ > p-NO₂: b > a > d > c.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-19", "exam": "JEE", "subject": "Chemistry", "chapter": "Atomic Structure", "type": "mcq", "difficulty": 2, "q": "Consider the following spectral lines for atomic hydrogen :\nA. First line of Paschen series\nB. Second line of Balmer series\nC. Third line of Paschen series\nD. Fourth line of Bracket series\nThe correct arrangement of the above lines in ascending order of energy is :", "options": ["D < C < A < B", "A < B < C < D", "D < A < C < B", "C < D < B < A"], "answer": 2, "hint": "ΔE ∝ 1/n₁² − 1/n₂².", "solution": "A: 1/9 − 1/16 = 0.0486. B: 1/4 − 1/16 = 0.1875. C: 1/9 − 1/36 = 0.0833. D (n 8→4): 1/16 − 1/64 = 0.0469. So D < A < C < B.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-20", "exam": "JEE", "subject": "Chemistry", "chapter": "Mole Concept", "type": "mcq", "difficulty": 1, "q": "Aqueous HCl reacts with MnO₂(s) to form MnCl₂(aq), Cl₂(g), and H₂O(l). What is the weight (in g) of Cl₂ liberated when 8.7 g of MnO₂(s) is reacted with excess aqueous HCl solution? (Given Molar mass in g mol⁻¹ Mn = 55, Cl = 35.5, O = 16, H = 1)", "options": ["14.2", "21.3", "7.1", "71"], "answer": 2, "hint": "MnO₂ + 4HCl → MnCl₂ + Cl₂ + 2H₂O.", "solution": "8.7/87 = 0.1 mol MnO₂ gives 0.1 mol Cl₂ = 7.1 g.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-21", "exam": "JEE", "subject": "Chemistry", "chapter": "Coordination Compounds", "type": "num", "difficulty": 2, "q": "Identify the metal ions among $\\mathrm{Co}^{2+}$, $\\mathrm{Ni}^{2+}$, $\\mathrm{Fe}^{2+}$, $\\mathrm{V}^{3+}$ and $\\mathrm{Ti}^{2+}$ having a spin-only magnetic moment value more than 3.0 BM. The sum of unpaired electrons present in the high spin octahedral complexes formed by those metal ions is _________ .", "answer": 7, "hint": "More than 3.0 BM needs at least 3 unpaired electrons (2 gives 2.83).", "solution": "High-spin Co²⁺ (d⁷, 3) and Fe²⁺ (d⁶, 4) qualify; Ni²⁺, V³⁺ and Ti²⁺ have 2. Sum = 7.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-22", "exam": "JEE", "subject": "Chemistry", "chapter": "Solutions", "type": "num", "difficulty": 1, "q": "The osmotic pressure of a living cell is 12 atm at 300 K. The strength of sodium chloride solution that is isotonic with the living cell at this temperature is ________ g L⁻¹. (Nearest integer)\nGiven : R = 0.08 L atm K⁻¹ mol⁻¹\nAssume complete dissociation of NaCl\n(Given: Molar mass of Na and Cl are 23 and 35.5 g mol⁻¹ respectively.)", "answer": 15, "hint": "π = iCRT with i = 2.", "solution": "C = 12/(2 × 0.08 × 300) = 0.25 M, and 0.25 × 58.5 = 14.6 ≈ 15 g/L.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-23", "exam": "JEE", "subject": "Chemistry", "chapter": "Ionic Equilibrium", "type": "num", "difficulty": 2, "q": "The first and second ionization constants of H₂X are $2.5\\times {10}^{-8}$ and $1.0\\times {10}^{-13}$ respectively.\nThe concentration of $X^{2-}$ in $0.1\\ \\mathrm{M}$ H₂X solution is ______ $\\times {10}^{-15}\\ \\mathrm{M}$. (Nearest Integer)", "answer": 100, "hint": "When K_a1 ≫ K_a2, [X²⁻] ≈ K_a2.", "solution": "[H⁺] ≈ [HX⁻], so [X²⁻] = K_a2 = 10⁻¹³ = 100 × 10⁻¹⁵ M.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-24", "exam": "JEE", "subject": "Chemistry", "chapter": "Solutions", "type": "num", "difficulty": 2, "q": "A substance 'X' (1.5 g) dissolved in 150 g of a solvent 'Y' (molar mass = 300 g mol⁻¹) led to an elevation of the boiling point by 0.5 K. The relative lowering in the vapour pressure of the solvent 'Y' is ______ × 10⁻². (nearest integer)\n[Given: K$_{b}$ of the solvent = 5.0 K kg mol⁻¹]\nAssume the solution to be dilute and no association or dissociation of X takes place in solution.", "answer": 3, "hint": "ΔT_b gives molality; relative lowering is the solute mole fraction.", "solution": "m = 0.5/5 = 0.1 mol/kg, so n(X) = 0.015 mol in 150 g (0.5 mol) of Y. x₂ = 0.015/0.515 ≈ 0.029 ≈ 3 × 10⁻².", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-25", "exam": "JEE", "subject": "Chemistry", "chapter": "Electrochemistry", "type": "num", "difficulty": 2, "q": "MX is a sparingly soluble salt that follows the given solubility equilibrium at 298 K.\n$\\mathrm{MX}(\\mathrm{s})\\rightleftharpoons \\mathrm{M}^+(\\mathrm{aq})+\\mathrm{X}^-(\\mathrm{aq});\\ \\mathrm{K}_{\\mathrm{sp}}={10}^{-10}$\nIf the standard reduction potential for M⁺ (aq) + e⁻ → M(s) is\n$(\\mathrm{E}_{\\ominus}^{\\mathrm{M}^+/\\mathrm{M}})=0.79\\ \\mathrm{V}$, then the value of the standard reduction potential for the metal/metal insoluble salt electrode $\\mathrm{E}_{\\ominus}^{\\mathrm{X}^-/\\mathrm{MX}(\\mathrm{s})/\\mathrm{M}}$ is ______ mV. (nearest integer)\n[Given: $\\frac{2.303RT}{F}=0.059\\ \\text{V}$]", "answer": 200, "hint": "E°(X⁻/MX/M) = E°(M⁺/M) + 0.059 log K_sp.", "solution": "0.79 + 0.059 × (−10) = 0.20 V = 200 mV.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-26", "exam": "JEE", "subject": "Mathematics", "chapter": "Conic Sections", "type": "mcq", "difficulty": 3, "q": "If the line $\\alpha x+4y=\\sqrt{7}$, where $\\alpha \\in \\mathbf{R}$, touches the ellipse $3x^2+4y^2=1$ at the point P in the first quadrant, then one of the focal distances of $P$ is :", "options": ["$\\frac{1}{\\sqrt{3}}-\\frac{1}{2\\sqrt{11}}$", "$\\frac{1}{\\sqrt{3}}-\\frac{1}{2\\sqrt{5}}$", "$\\frac{1}{\\sqrt{3}}+\\frac{1}{2\\sqrt{5}}$", "$\\frac{1}{\\sqrt{3}}+\\frac{1}{2\\sqrt{7}}$"], "answer": 3, "hint": "Match the line with the tangent 3x₁x + 4y₁y = 1 to get P; then use focal distances a ± ex₁.", "solution": "Comparing gives P = (1/√7, 1/√7). a² = 1/3, b² = 1/4, e = 1/2, so focal distances = 1/√3 ± 1/(2√7).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-27", "exam": "JEE", "subject": "Mathematics", "chapter": "Quadratic Equations", "type": "mcq", "difficulty": 1, "q": "Let $\\alpha$ and $\\beta$ be the roots of the equation $x^2+2ax+(3a+10)=0$ such that $\\alpha \\lt 1\\lt \\beta$. Then the set of all possible values of $a$ is :", "options": ["$(-\\infty ,\\frac{-11}{5})\\cup (5,\\infty )$", "$(-\\infty ,\\frac{-11}{5})$", "$(-\\infty ,-3)$", "$(-\\infty ,-2)\\cup (5,\\infty )$"], "answer": 1, "hint": "1 lies between the roots ⇔ f(1) < 0 (leading coefficient positive).", "solution": "f(1) = 5a + 11 < 0 ⇒ a < −11/5.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-28", "exam": "JEE", "subject": "Mathematics", "chapter": "Conic Sections", "type": "mcq", "difficulty": 3, "q": "Let $y^2=12x$ be the parabola with its vertex at $O$. Let $P$ be a point on the parabola and $A$ be a point on the $x$-axis such that $\\angle OPA={90}^{\\circ}$. Then the locus of the centroid of such triangles $OPA$ is:", "options": ["$y^2-4x+8=0$", "$y^2-2x+8=0$", "$y^2-9x+6=0$", "$y^2-6x+4=0$"], "answer": 1, "hint": "Take P(3t², 6t) and impose PO ⊥ PA.", "solution": "OP ⊥ PA gives A = (3t² + 12, 0). Centroid (2t² + 4, 2t) ⇒ y² = 2x − 8.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-29", "exam": "JEE", "subject": "Mathematics", "chapter": "Matrices & Determinants", "type": "mcq", "difficulty": 2, "q": "If the system of equations\n$3x+y+4z=3$\n$2x+\\alpha y-z=-3$\n$x+2y+z=4$\nhas no solution, then the value of $\\alpha$ is equal to:", "options": ["13", "4", "19", "23"], "answer": 2, "hint": "No solution needs D = 0 with the system inconsistent.", "solution": "D = 19 − α = 0 ⇒ α = 19. Then E₂ = −3E₁ + 11E₃ on the left side, but the right sides give 35 ≠ −3: inconsistent.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-30", "exam": "JEE", "subject": "Mathematics", "chapter": "Complex Numbers", "type": "mcq", "difficulty": 3, "q": "Let $z$ be the complex number satisfying $|z-5|\\le 3$ and having maximum positive principal argument.\nThen $34{|\\frac{5z-12}{5iz+16}|}^2$ is equal to:", "options": ["20", "26", "12", "16"], "answer": 0, "hint": "The maximum argument occurs at the tangent from the origin to the circle.", "solution": "Tangent length 4 and sin θ = 3/5 ⇒ z = (16 + 12i)/5. Then |4 + 12i|²/|4 + 16i|² = 160/272, and 34 × 10/17 = 20.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-31", "exam": "JEE", "subject": "Mathematics", "chapter": "Area Under Curves", "type": "mcq", "difficulty": 2, "q": "If the area of the region $\\{(x,y):1-2x\\le y\\le 4-x^2,\\ x\\ge 0,\\ y\\ge 0\\}$ is $\\frac{\\alpha }{\\beta }$, $\\alpha ,\\beta \\in \\mathbb{N},\\gcd (\\alpha ,\\beta )=1$, then the value of $(\\alpha +\\beta )$ is:", "options": ["73", "85", "67", "91"], "answer": 0, "hint": "Split at x = 1/2, where the line meets the x-axis.", "solution": "Area = ∫₀²(4 − x²)dx − ∫₀^{1/2}(1 − 2x)dx = 16/3 − 1/4 = 61/12 ⇒ α + β = 73.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-32", "exam": "JEE", "subject": "Mathematics", "chapter": "Sequences & Series", "type": "mcq", "difficulty": 3, "q": "The positive integer n, for which the solutions of the equation\n$x(x+2)+(x+2)(x+4)+\\cdots +(x+2n-2)(x+2n)=\\frac{8n}{3}$ are two consecutive even integers, is :", "options": ["3", "6", "9", "12"], "answer": 0, "hint": "Sum the series to get a quadratic in x; two consecutive even roots differ by 2.", "solution": "The equation reduces to x² + 2nx + (4n² − 12)/3 = 0. Setting the discriminant to 4 gives n = 3, with roots −2 and −4.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-33", "exam": "JEE", "subject": "Mathematics", "chapter": "Conic Sections", "type": "mcq", "difficulty": 2, "q": "Let one end of a focal chord of the parabola $y^2=16x$ be $(16,16)$. If $P(\\alpha ,\\ \\beta )$ divides this focal chord internally in the ratio $5:2$, then the minimum value of $\\alpha +\\beta$ is equal to:", "options": ["5", "7", "22", "16"], "answer": 1, "hint": "The ends of a focal chord have t₁t₂ = −1.", "solution": "The other end is (1, −4). The two section points are (37/7, 12/7) and (82/7, 72/7), with sums 7 and 22 ⇒ minimum 7.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-34", "exam": "JEE", "subject": "Mathematics", "chapter": "Sets & Relations", "type": "mcq", "difficulty": 2, "q": "Let $A=\\{x:|x^2-10|\\le 6\\}$ and $B=\\{x:|x-2|\\gt 1\\}$. Then", "options": ["$A\\cup B=(-\\infty ,1]\\cup (2,\\infty )$", "$B-A=(-\\infty ,-4)\\cup (-2,1)\\cup (4,\\infty )$", "$A-B=[2,3)$", "$A\\cap B=[-4,-2]\\cup [3,4]$"], "answer": 1, "hint": "A = [−4, −2] ∪ [2, 4]; B = (−∞, 1) ∪ (3, ∞).", "solution": "B − A = (−∞, −4) ∪ (−2, 1) ∪ (4, ∞). (D fails: A ∩ B has (3, 4], not [3, 4].)", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-35", "exam": "JEE", "subject": "Mathematics", "chapter": "3D Geometry", "type": "mcq", "difficulty": 2, "q": "Let the line L pass through the point $(-3,5,2)$ and make equal angles with the positive coordinate axes. If the distance of L from the point $(-2,r,1)$ is $\\sqrt{\\frac{14}{3}}$, then the sum of all possible values of $r$ is :", "options": ["16", "12", "6", "10"], "answer": 3, "hint": "The direction is (1, 1, 1); d² = |PQ|² − (PQ·û)².", "solution": "2 + (2/3)(r − 5)² = 14/3 ⇒ r = 3 or 7, sum 10.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-36", "exam": "JEE", "subject": "Mathematics", "chapter": "Application of Derivatives", "type": "mcq", "difficulty": 3, "q": "Let $f:\\mathbb{R}\\rightarrow \\mathbb{R}$ be a twice differentiable function such that $f''(x)\\gt 0$ for all $x\\in \\mathbb{R}$ and $f'(a-1)=0$, where $a$ is a real number.\nLet $g(x)=f(\\tan^2x-2\\tan x+a),\\ 0\\lt x\\lt \\frac{\\pi }{2}$.\nConsider the following two statements:\n(I) g is increasing in $(0,\\frac{\\pi }{4})$\n(II) g is decreasing in $(\\frac{\\pi }{4},\\frac{\\pi }{2})$\nThen,", "options": ["Both (I) and (II) are True", "Neither (I) nor (II) is True", "Only (I) is True", "Only (II) is True"], "answer": 1, "hint": "u = (tan x − 1)² + a − 1 ≥ a − 1, so f′(u) ≥ 0; the sign of g′ follows u′.", "solution": "u′ < 0 on (0, π/4) and u′ > 0 on (π/4, π/2): g decreases, then increases. Both statements are false.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-37", "exam": "JEE", "subject": "Mathematics", "chapter": "Sequences & Series", "type": "mcq", "difficulty": 2, "q": "Let $a_1,\\frac{a_2}{2},\\frac{a_3}{2^2},\\ldots ,\\frac{a_{10}}{2^9}$ be a G.P. of common ratio $\\frac{1}{\\sqrt{2}}$. If $a_1+a_2+\\ldots +a_{10}=62$, then $a_1$ is equal to:", "options": ["$\\sqrt{2}-1$", "$2(\\sqrt{2}-1)$", "$2-\\sqrt{2}$", "$2(2-\\sqrt{2})$"], "answer": 1, "hint": "a_k = a₁(√2)^{k−1}.", "solution": "a₁((√2)¹⁰ − 1)/(√2 − 1) = 62 ⇒ a₁ = 2(√2 − 1).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-38", "exam": "JEE", "subject": "Mathematics", "chapter": "Differential Equations", "type": "mcq", "difficulty": 3, "q": "Let $y=y(x)$ be the solution of the differential equation $\\sec x\\frac{dy}{dx}-2y=2+3\\sin x$, $x\\in (-\\frac{\\pi }{2},\\frac{\\pi }{2})$,\n$y(0)=-\\frac{7}{4}$. Then $y(\\frac{\\pi }{6})$ is equal to :", "options": ["$-\\frac{5}{2}$", "$-3\\sqrt{2}-7$", "$-\\frac{5}{4}$", "$-3\\sqrt{3}-7$"], "answer": 0, "hint": "Linear in y with integrating factor e^{−2 sin x}; substitute s = sin x.", "solution": "y = −7/4 − (3/2)sin x + Ce^{2 sin x}, and y(0) = −7/4 ⇒ C = 0 ⇒ y(π/6) = −5/2.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-39", "exam": "JEE", "subject": "Mathematics", "chapter": "Differentiation", "type": "mcq", "difficulty": 2, "q": "Let $f(x)=x^3+x^2f'(1)+2xf''(2)+f'''(3)$, $x\\in \\mathbb{R}$. Then the value of $f'(5)$ is :", "options": ["$\\frac{657}{5}$", "$\\frac{117}{5}$", "$\\frac{2}{5}$", "$\\frac{62}{5}$"], "answer": 1, "hint": "f′(1), f″(2) and f‴(3) are constants; write f = x³ + ax² + bx + c.", "solution": "a = 3 + 2a + b and b = 2(12 + 2a) ⇒ a = −27/5, b = 12/5 ⇒ f′(5) = 75 + 10a + b = 117/5.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-40", "exam": "JEE", "subject": "Mathematics", "chapter": "Sets & Relations", "type": "mcq", "difficulty": 2, "q": "Let $A=\\{2,3,5,7,9\\}$. Let $R$ be the relation on $A$ defined by $xRy$ if and only if $2x\\le 3y$. Let $l$ be the number of elements in $R$, and $m$ be the minimum number of elements required to be added in $R$ to make it a symmetric relation. Then $l+m$ is equal to:", "options": ["21", "25", "23", "27"], "answer": 1, "hint": "Count the pairs with y ≥ 2x/3, then the missing reverse pairs.", "solution": "l = 5 + 5 + 3 + 3 + 2 = 18. Missing reverses: (5,2), (7,2), (9,2), (5,3), (7,3), (9,3), (9,5) ⇒ m = 7, so l + m = 25.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-41", "exam": "JEE", "subject": "Mathematics", "chapter": "Matrices & Determinants", "type": "mcq", "difficulty": 3, "q": "For the matrices $A=\\begin{bmatrix}3 & -4 \\\\ 1 & -1\\end{bmatrix}$ and $B=\\begin{bmatrix}-29 & 49 \\\\ -13 & 18\\end{bmatrix}$, if $(A^{15}+B)\\begin{bmatrix}x \\\\ y\\end{bmatrix}=\\begin{bmatrix}0 \\\\ 0\\end{bmatrix}$, then among the following which one is true?", "options": ["$x=16$, $y=3$", "$x=5$, $y=7$", "$x=11$, $y=2$", "$x=18$, $y=11$"], "answer": 2, "hint": "(A − I)² = 0, so A¹⁵ = I + 15(A − I).", "solution": "A¹⁵ = [[31, −60], [15, −29]]; adding B gives [[2, −11], [2, −11]] ⇒ 2x = 11y ⇒ (11, 2).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-42", "exam": "JEE", "subject": "Mathematics", "chapter": "Probability", "type": "mcq", "difficulty": 2, "q": "A random variable X takes values 0, 1, 2, 3 with probabilities $\\frac{2a+1}{30}$, $\\frac{8a-1}{30}$, $\\frac{4a+1}{30}$, $b$ respectively, where $a,b\\in \\mathbb{R}$.\nLet $\\mu$ and $\\sigma$ respectively be the mean and standard deviation of $X$ such that $\\sigma^2+\\mu^2=2$.\nThen $\\frac{a}{b}$ is equal to:", "options": ["12", "60", "30", "3"], "answer": 1, "hint": "Use Σp = 1 and σ² + μ² = E(X²).", "solution": "b = (29 − 14a)/30 and (24a + 3)/30 + 9b = 2 ⇒ a = 2, b = 1/30 ⇒ a/b = 60.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-43", "exam": "JEE", "subject": "Mathematics", "chapter": "Vector Algebra", "type": "mcq", "difficulty": 3, "q": "For a triangle $ABC$, let $\\vec{p}=\\overrightarrow{BC},\\vec{q}=\\overrightarrow{CA}$ and $\\vec{r}=\\overrightarrow{BA}$. If $|\\vec{p}|=2\\sqrt{3},|\\vec{q}|=2$ and $\\cos \\theta =\\frac{1}{\\sqrt{3}}$, where $\\theta$ is the angle between $\\vec{p}$ and $\\vec{q}$, then $|\\vec{p}\\times (\\vec{q}-3\\vec{r})|^2+3|\\vec{r}|^2$ is equal to :", "options": ["200", "220", "410", "340"], "answer": 0, "hint": "BC + CA = BA, so r⃗ = p⃗ + q⃗.", "solution": "p⃗ × (q⃗ − 3r⃗) = −2 p⃗ × q⃗, giving 4 × 12 × 4 × (2/3) = 128. |r⃗|² = 12 + 4 + 8 = 24 ⇒ 128 + 72 = 200.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-44", "exam": "JEE", "subject": "Mathematics", "chapter": "Permutations & Combinations", "type": "mcq", "difficulty": 1, "q": "The largest $n\\in \\mathbb{N}$, for which $7^n$ divides $101!$, is :", "options": ["18", "15", "19", "16"], "answer": 3, "hint": "Legendre: Σ⌊101/7ᵏ⌋.", "solution": "14 + 2 = 16.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-45", "exam": "JEE", "subject": "Mathematics", "chapter": "3D Geometry", "type": "mcq", "difficulty": 3, "q": "Let the line $L_1$ be parallel to the vector $-3\\hat{i}+2\\hat{j}+4\\hat{k}$ and pass through the point $(2,6,7)$, and the line $L_2$ be parallel to the vector $2\\hat{i}+\\hat{j}+3\\hat{k}$ and pass through the point $(4,3,5)$. If the line $L_3$ is parallel to the vector $-3\\hat{i}+5\\hat{j}+16\\hat{k}$ and intersects the lines $L_1$ and $L_2$ at the points $C$ and $D$, respectively, then ${|\\overrightarrow{CD}|}^2$ is equal to:", "options": ["290", "171", "89", "312"], "answer": 0, "hint": "Write C and D with parameters s and t, and set D − C ∥ (−3, 5, 16).", "solution": "Solving gives s = −3 and λ = 1, so CD = (−3, 5, 16) and |CD|² = 9 + 25 + 256 = 290.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-46", "exam": "JEE", "subject": "Mathematics", "chapter": "Definite Integration", "type": "num", "difficulty": 3, "q": "Let $[\\cdot ]$ denote the greatest integer function and $f(x)=\\lim _{n\\rightarrow \\infty}\\frac{1}{n^3}\\sum _{k=1}^n[\\frac{k^2}{3^x}]$. Then $12\\sum _{j=1}^{\\infty}f(j)$ is equal to ________.", "answer": 2, "hint": "The floor changes the sum by only O(n), which is negligible against n³.", "solution": "f(x) = 1/(3·3ˣ) ⇒ Σ f(j) = (1/3)(1/2) = 1/6 ⇒ 12 × 1/6 = 2.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-47", "exam": "JEE", "subject": "Mathematics", "chapter": "Circles", "type": "num", "difficulty": 3, "q": "If $P$ is a point on the circle $x^2+y^2=4,Q$ is a point on the straight line $5x+y+2=0$ and $x-y+1=0$ is the perpendicular bisector of PQ , then 13 times the sum of abscissa of all such points P is $\\_\\_\\_\\_$ .", "answer": 2, "hint": "Q is the mirror image of P in x − y + 1 = 0: Q = (y − 1, x + 1).", "solution": "Q on 5x + y + 2 = 0 ⇒ x + 5y = 2. Meeting x² + y² = 4 gives x = 2 and x = −24/13. The sum is 2/13, and 13 × 2/13 = 2.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-48", "exam": "JEE", "subject": "Mathematics", "chapter": "Binomial Theorem", "type": "num", "difficulty": 3, "q": "If $(\\frac{1}{{}^{15}\\mathrm{C}_0}+\\frac{1}{{}^{15}\\mathrm{C}_1})(\\frac{1}{{}^{15}\\mathrm{C}_1}+\\frac{1}{{}^{15}\\mathrm{C}_2})\\ldots (\\frac{1}{{}^{15}\\mathrm{C}_{12}}+\\frac{1}{{}^{15}\\mathrm{C}_{13}})=\\frac{\\alpha^{13}}{{}^{14}\\mathrm{C}_0{}^{14}\\mathrm{C}_1\\cdots {}^{14}\\mathrm{C}_{12}}$, then $30\\alpha$ is equal to\n$\\_\\_\\_\\_$ .", "answer": 32, "hint": "1/ⁿC_r + 1/ⁿC_{r+1} = (n + 1)/(n · ⁿ⁻¹C_r).", "solution": "Each factor is 16/(15 · ¹⁴C_r) ⇒ α = 16/15 ⇒ 30α = 32.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-49", "exam": "JEE", "subject": "Mathematics", "chapter": "Definite Integration", "type": "num", "difficulty": 3, "q": "If $\\int _0^14\\cot^{-1}(1-2x+4x^2)\\mathrm{d}x={\\mathrm{a}\\ \\tan}^{-1}(2)-{\\mathrm{b}\\ \\log}_{\\mathrm{e}}(5)$, where $\\mathrm{a},\\mathrm{b}\\in \\mathrm{N}$, then $(2\\mathrm{a}+\\mathrm{b})$ is equal to $\\_\\_\\_\\_$ .", "answer": 9, "hint": "With u = 2x, cot⁻¹(1 − u + u²) = tan⁻¹u + tan⁻¹(1 − u).", "solution": "2∫₀²tan⁻¹u du + 2∫₋₁¹tan⁻¹w dw = 2(2 tan⁻¹2 − ½ ln 5) + 0 = 4 tan⁻¹2 − ln 5 ⇒ 2a + b = 9.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-50", "exam": "JEE", "subject": "Mathematics", "chapter": "Inverse Trigonometry", "type": "num", "difficulty": 2, "q": "Let the maximum value of ${(\\sin^{-1}x)}^2+{(\\cos^{-1}x)}^2$ for $x\\in [-\\frac{\\sqrt{3}}{2},\\frac{1}{\\sqrt{2}}]$ be $\\frac{\\mathrm{m}}{\\mathrm{n}}\\pi^2$, where $\\gcd (\\mathrm{m},\\mathrm{n})=1$. Then $\\mathrm{m}+\\mathrm{n}$ is equal to $\\_\\_\\_\\_$。", "answer": 65, "hint": "With θ = sin⁻¹x, f = θ² + (π/2 − θ)², θ ∈ [−π/3, π/4].", "solution": "f is minimum at θ = π/4 and maximum at θ = −π/3: 2π²/9 + π²/3 + π²/4 = 29π²/36 ⇒ 65.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-51", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 1, "q": "A spherical body of radius $r$ and density $\\sigma$ falls freely through a viscous liquid having density $\\rho$ and viscosity $\\eta$ and attains a terminal velocity $v_0$. Estimated maximum error in the quantity $\\eta$ is : (Ignore errors associated with $\\sigma$, $\\rho$ and $g$, gravitational acceleration)", "options": ["$2[\\frac{\\Delta r}{r}-\\frac{\\Delta v_0}{v_0}]$", "$2[\\frac{\\Delta r}{r}+\\frac{\\Delta v_0}{v_0}]$", "$\\frac{2\\Delta r}{r}+\\frac{\\Delta v_0}{v_0}$", "$2\\frac{\\Delta r}{r}-\\frac{\\Delta v_0}{v_0}$"], "answer": 2, "hint": "From Stokes' law, η = 2r²(σ − ρ)g/(9v₀).", "solution": "Δη/η = 2Δr/r + Δv₀/v₀ (errors add).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-52", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 1, "q": "Keeping the significant figures in view, the sum of the physical quantities 52.01 m, 153.2 m and 0.123 m is :", "options": ["205.3 m", "205 m", "205.333 m", "205.33 m"], "answer": 0, "hint": "In a sum, round to the fewest decimal places.", "solution": "52.01 + 153.2 + 0.123 = 205.333, which rounds to 205.3 m (one decimal place, set by 153.2).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-53", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 1, "q": "A large drum having radius $R$ is spinning around its axis with angular velocity $\\omega$, as shown in figure.\nThe minimum value of $\\omega$ so that a body of mass $M$ remains stuck to the inner wall of the drum, taking the coefficient of friction between the drum surface and mass $M$ as $\\mu$, is :", "img": "figures/pyq/jm26-0121s2-53.png", "imgAlt": "Drum of radius R spinning with ω; mass M on the inner wall", "options": ["$\\sqrt{\\frac{2g}{\\mu R}}$", "$\\sqrt{\\frac{g}{2\\mu R}}$", "$\\sqrt{\\frac{\\mu g}{R}}$", "$\\sqrt{\\frac{g}{\\mu R}}$"], "answer": 3, "hint": "The wall's normal reaction supplies the centripetal force; friction holds the body up.", "solution": "μMω²R ≥ Mg ⇒ ω_min = √(g/(μR)).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-54", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 2, "q": "Two known resistances of $R\\ \\Omega$ and $2R\\ \\Omega$ and one unknown resistance $X\\ \\Omega$ are connected in a circuit as shown in the figure. If the equivalent resistance between points $A$ and $B$ in the circuit is $X\\ \\Omega$, then the value of $X$ is __________ $\\Omega$.", "img": "figures/pyq/jm26-0121s2-54.png", "imgAlt": "2R and X in series, in parallel with R, between A and B", "options": ["$2(\\sqrt{3}-1)R$", "$R$", "$(\\sqrt{3}-1)R$", "$(\\sqrt{3}+1)R$"], "answer": 2, "hint": "(2R + X) in parallel with R must equal X.", "solution": "R(2R + X)/(3R + X) = X ⇒ X² + 2RX − 2R² = 0 ⇒ X = (√3 − 1)R.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-55", "exam": "JEE", "subject": "Physics", "chapter": "Kinetic Theory", "type": "mcq", "difficulty": 1, "q": "The r.m.s. speed of oxygen molecules at 47 °C is equal to that of the hydrogen molecules kept at _________ °C. (Mass of oxygen molecule/mass of hydrogen molecule = 32/2)", "options": ["-100", "-253", "-20", "-235"], "answer": 1, "hint": "v_rms ∝ √(T/M).", "solution": "T_H = 320 × 2/32 = 20 K = −253 °C.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-56", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 2, "q": "The total length of potentiometer wire AB is 50 cm in the arrangement as shown in the figure. If P is the point where the galvanometer shows zero reading then the length AP is ________ cm.", "img": "figures/pyq/jm26-0121s2-56.png", "imgAlt": "6 Ω and 4 Ω across wire AB with galvanometer to jockey P", "options": ["25", "30", "15", "20"], "answer": 1, "hint": "This is a metre-bridge balance: AP/PB = 6/4.", "solution": "AP = 50 × 6/10 = 30 cm.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-57", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "Surface tension of two liquids (having same densities), $T_1$ and $T_2$, are measured using capillary rise method utilizing two tubes with inner radii of $r_1$ and $r_2$ where $r_1\\gt r_2$. The measured liquid heights in these tubes are $h_1$ and $h_2$ respectively. [Ignore the weight of the liquid above the lowest point of miniscus]. The heights $h_1$ and $h_2$ and surface tensions $T_1$ and $T_2$ satisfy the relation :", "options": ["$h_1\\gt h_2$ and $T_1=T_2$", "$h_1\\lt h_2$ and $T_1=T_2$", "$h_1\\gt h_2$ and $T_1\\lt T_2$", "$h_1=h_2$ and $T_1=T_2$"], "answer": 1, "hint": "h = 2T cos θ/(rρg); test each option for consistency.", "solution": "With equal ρ, h ∝ T/r. Only 'h₁ < h₂ with T₁ = T₂' is consistent with r₁ > r₂; every other option contradicts h ∝ T/r.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-58", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "num", "difficulty": 2, "q": "A particle having electric charge $3\\times {10}^{-19}\\mathrm{C}$ and mass $6\\times {10}^{-27}\\ \\mathrm{kg}$ is accelerated by applying an electric potential of 1.21 V .\nWavelength of the matter wave associated with the particle is $\\alpha \\times {10}^{-12}\\ \\mathrm{m}$. The value of $\\alpha$ is $\\_\\_\\_\\_$ .\n(Take Planck's constant $=6.6\\times {10}^{-34}\\ \\mathrm{J}.\\mathrm{s}$ )", "answer": 10, "hint": "λ = h/√(2mqV).", "solution": "√(2 × 6×10⁻²⁷ × 3×10⁻¹⁹ × 1.21) = 6.6×10⁻²³, so λ = 10⁻¹¹ m = 10 × 10⁻¹² m.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-59", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "mcq", "difficulty": 1, "q": "Given below are two statements :\nStatement I : In a Young's double slit experiment, the angular separation of fringes will increase as the screen is moved away from the plane of the slits\nStatement II : In a Young's double slit experiment, the angular separation of fringes will increase when monochromatic source is replaced by another monochromatic source of higher wavelength\nIn the light of the above statements, choose the correct answer from the options given below :", "options": ["Both Statement I and Statement II are true", "Statement I is true but Statement II is false", "Statement I is false but Statement II is true", "Both Statement I and Statement II are false"], "answer": 2, "hint": "Angular fringe width = λ/d.", "solution": "It doesn't depend on D (I is false) and grows with λ (II is true).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-60", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 1, "q": "The kinetic energy of a simple harmonic oscillator is oscillating with angular frequency of 176 rad/s. The frequency of this simple harmonic oscillator is ______ Hz. [ take $\\pi =\\frac{22}{7}$ ]", "options": ["88", "14", "28", "176"], "answer": 1, "hint": "KE ∝ cos²ωt, which oscillates at 2ω.", "solution": "2ω = 176 ⇒ ω = 88 rad/s ⇒ f = 88 × 7/44 = 14 Hz.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-61", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "Two cars A and B each of mass ${10}^3$ kg are moving on parallel tracks separated by a distance of 10 m, in same direction with speeds 72 km/h and 36 km/h. The magnitude of angular momentum of car A with respect to car B is ________ J·s.", "options": ["$3.6\\times {10}^5$", "${10}^5$", "$3\\times {10}^5$", "$2\\times {10}^5$"], "answer": 1, "hint": "L = m v_rel d⊥.", "solution": "10³ × (20 − 10) × 10 = 10⁵ J·s.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-62", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Waves", "type": "num", "difficulty": 2, "q": "An electromagnetic wave of frequency 100 MHz propagates through a medium of conductivity, $\\sigma =10\\ \\mathrm{mho}/\\mathrm{m}$. The ratio of maximum conduction current density to maximum displacement current density is $\\_\\_\\_\\_$.\n$[\\text{ Take }\\frac{1}{4\\pi \\epsilon_0}=9\\times {10}^9\\ \\mathrm{Nm}^2/\\mathrm{C}^2]$", "answer": 1800, "hint": "J_c/J_d = σ/(ωε₀).", "solution": "ωε₀ = 2π × 10⁸/(4π × 9×10⁹) = 1/180 ⇒ ratio = 10 × 180 = 1800.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-63", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "num", "difficulty": 1, "q": "The terminal velocity of a metallic ball of radius 6 mm in a viscous fluid is $20\\ \\mathrm{cm}/\\mathrm{s}$. The terminal velocity of another ball of same material and having radius 3 mm in the same fluid will be\n$\\_\\_\\_\\_$ $\\mathrm{cm}/\\mathrm{s}$.", "answer": 5, "hint": "v_t ∝ r².", "solution": "20 × (3/6)² = 5 cm/s.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-64", "exam": "JEE", "subject": "Physics", "chapter": "Magnetic Effects of Current", "type": "mcq", "difficulty": 3, "q": "An infinitely long straight wire carrying current $I$ is bent in a planar shape as shown in the diagram. The radius of the circular part is $r$. The magnetic field at the centre $O$ of the circular loop is :", "img": "figures/pyq/jm26-0121s2-64.png", "imgAlt": "Long straight wire along y with a circular loop of radius r above it; axes x, y, z", "options": ["$-\\frac{\\mu_0}{2\\pi }\\frac{I}{r}(\\pi +1)\\hat{i}$", "$-\\frac{\\mu_0}{2\\pi }\\frac{I}{r}(\\pi -1)\\hat{i}$", "$\\frac{\\mu_0}{2\\pi }\\frac{I}{r}(\\pi +1)\\hat{i}$", "$\\frac{\\mu_0}{2\\pi }\\frac{I}{r}(\\pi -1)\\hat{i}$"], "answer": 1, "hint": "Superpose the infinite straight wire (+x̂ at O) and the full loop; the loop runs clockwise as drawn, so its field is −x̂.", "solution": "B = (μ₀I/2πr)x̂ − (μ₀I/2r)x̂ = −(μ₀I/2πr)(π − 1)x̂.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-65", "exam": "JEE", "subject": "Physics", "chapter": "Thermodynamics", "type": "num", "difficulty": 1, "q": "A diatomic gas $(\\gamma =1.4)$ does 100 J of work when it is expanded isobarically. Then the heat given to the gas $\\_\\_\\_\\_$ J.", "answer": 350, "hint": "Isobaric: Q/W = C_p/R = γ/(γ − 1).", "solution": "Q = 100 × 1.4/0.4 = 350 J.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-66", "exam": "JEE", "subject": "Physics", "chapter": "Atoms", "type": "mcq", "difficulty": 1, "q": "The energy of an electron in an orbit of the Bohr's atom is $-0.04E_0$ eV where $E_0$ is the ground state energy. If $L$ is the angular momentum of the electron in this orbit and $h$ is the Planck's constant, then\n$\\frac{2\\pi L}{h}$ is ________ :", "options": ["6", "2", "5", "4"], "answer": 2, "hint": "E_n = E₀/n² and L = nh/2π.", "solution": "1/n² = 0.04 ⇒ n = 5 ⇒ 2πL/h = 5.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-67", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "num", "difficulty": 2, "q": "In a Young's double slit experiment set up, the two slits are kept 0.4 mm apart and screen is placed at 1 m from slits. If a thin transparent sheet of thickness $20\\mu \\ \\mathrm{m}$ is introduced in front of one of the slits then center bright fringe shifts by 20 mm on the screen.\nThe refractive index of transparent sheet is given by $\\frac{\\alpha }{10}$, where $\\alpha$ is $\\_\\_\\_\\_$.", "answer": 14, "hint": "Fringe shift = (μ − 1)tD/d.", "solution": "20×10⁻³ = (μ − 1) × 20×10⁻⁶ × 1/(0.4×10⁻³) ⇒ μ − 1 = 0.4 ⇒ μ = 14/10.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-68", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "As shown in the diagram, when the incident ray is parallel to base of the prism, the emergent ray grazes along the second surface.\nIf refractive index of the material of prism is $\\sqrt{2}$, the angle $\\theta$ of prism is.", "img": "figures/pyq/jm26-0121s2-68.png", "imgAlt": "Prism with base angles 45° and θ; ray parallel to base grazes second face", "options": ["${75}^{\\circ}$", "${90}^{\\circ}$", "${60}^{\\circ}$", "${45}^{\\circ}$"], "answer": 2, "hint": "i = 45° at the first face; grazing emergence means r₂ = critical angle.", "solution": "sin r₁ = sin 45°/√2 ⇒ r₁ = 30°, and r₂ = C = 45°. So A = 75° and θ = 180° − 45° − 75° = 60°.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-69", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 1, "q": "A body of mass 2 kg is moving along x-direction such that its displacement as function of time is given by $x(t)=\\alpha t^2+\\beta t+\\gamma$ m, where $\\alpha =1\\ m/s^2$, $\\beta =1\\ m/s$ and $\\gamma =1\\ m$. The work done on the body during the time interval $t=2\\ s$ to $t=3\\ s$, is ________ J.", "options": ["42", "24", "49", "12"], "answer": 1, "hint": "Work = ΔKE with v = 2αt + β.", "solution": "v(2) = 5 and v(3) = 7 ⇒ W = ½ × 2 × (49 − 25) = 24 J.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-70", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 1, "q": "A battery with EMF $E$ and internal resistance $r$ is connected across a resistance $R$. The power consumption in $R$ will be maximum when:", "options": ["$R=\\sqrt{2}\\ r$", "$R=2r$", "$R=\\frac{r}{2}$", "$R=r$"], "answer": 3, "hint": "Maximum power transfer theorem.", "solution": "P = E²R/(R + r)² is maximum at R = r.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-71", "exam": "JEE", "subject": "Physics", "chapter": "Electrostatics", "type": "mcq", "difficulty": 3, "q": "Consider two identical metallic spheres of radius $R$ each having charge $Q$ and mass $m$. Their centers have an initial separation of $4R$. Both the spheres are given an initial speed of $u$ towards each other. The minimum value of $u$, so that they can just touch each other is:\n(Take $k=\\frac{1}{4\\pi \\epsilon_0}$ and assume $kQ^2\\gt Gm^2$ where $G$ is the Gravitational constant)", "options": ["$\\sqrt{\\frac{kQ^2}{4mR}(1+\\frac{Gm^2}{kQ^2})}$", "$\\sqrt{\\frac{kQ^2}{2mR}(1-\\frac{Gm^2}{2kQ^2})}$", "$\\sqrt{\\frac{kQ^2}{2mR}(1-\\frac{Gm^2}{kQ^2})}$", "$\\sqrt{\\frac{kQ^2}{4mR}(1-\\frac{Gm^2}{kQ^2})}$"], "answer": 3, "hint": "Energy conservation from separation 4R to 2R, with both the electric and gravitational PE.", "solution": "2 × ½mu² = kQ²(1/2R − 1/4R) − Gm²(1/2R − 1/4R) ⇒ u = √(kQ²/(4mR) × (1 − Gm²/kQ²)).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-72", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 2, "q": "A capacitor C is first charged fully with potential difference of $V_0$ and disconnected from the battery. The charged capacitor is connected across an inductor having inductance L. In $t$ s, 25% of the initial energy in the capacitor is transferred to the inductor. The value of $t$ is ________ s.", "options": ["$\\frac{\\pi \\sqrt{LC}}{3}$", "$\\frac{\\pi \\sqrt{LC}}{2}$", "$\\pi \\sqrt{\\frac{LC}{2}}$", "$\\frac{\\pi \\sqrt{LC}}{6}$"], "answer": 3, "hint": "In LC oscillation, U_C = U₀cos²ωt.", "solution": "cos²ωt = 3/4 ⇒ ωt = π/6 ⇒ t = π√(LC)/6.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-73", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "A river of width 200 m is flowing from west to east with a speed of 18 km/h. A boat, moving with speed of 36 km/h in still water, is made to travel one-round trip (bank to bank of the river). Minimum time taken by the boat for this journey and also the displacement along the river bank are ______ and ______ respectively.", "options": ["20 s and 100 m", "40 s and 100 m", "40 s and 200 m", "40 s and 0 m"], "answer": 2, "hint": "Minimum time: head straight across both ways.", "solution": "20 s each way ⇒ 40 s in total. Drift is 5 m/s × 40 s = 200 m downstream.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-74", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "The pulley shown in figure is made using a thin rim and two rods of length equal to diameter of the rim. The rim and each rod have a mass of M. Two blocks of mass of M and m are attached to two ends of a light string passing over the pulley, which is hinged to rotate freely in vertical plane about its center. The magnitudes of the acceleration experienced by the blocks is ________ (assume no slipping of string on pulley).", "img": "figures/pyq/jm26-0121s2-74.png", "imgAlt": "Pulley made of a rim and two crossed rods; blocks m and M hang on either side", "options": ["$\\frac{(M-m)g}{[(\\frac{8}{3})M+m]}$", "$\\frac{(M-m)g}{2M+m}$", "$\\frac{(M-m)g}{M+m}$", "$\\frac{(M-m)g}{[(\\frac{13}{6})M+m]}$"], "answer": 0, "hint": "I = rim MR² + two rods of length 2R about their centres, 2 × M(2R)²/12.", "solution": "I = (5/3)MR² ⇒ a = (M − m)g/(M + m + 5M/3) = (M − m)g/((8/3)M + m).", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
  {"id": "jm26-0121s2-75", "exam": "JEE", "subject": "Physics", "chapter": "Semiconductors", "type": "mcq", "difficulty": 2, "q": "The charge stored by the capacitor C in the given circuit in the steady state is __________ µC.", "img": "figures/pyq/jm26-0121s2-75.png", "imgAlt": "Parallel branches: 2.5 V cell with 1 Ω, 5 µF capacitor with 2 Ω, reverse diode with 3 Ω, forward diode with 4 Ω", "options": ["7.5", "5", "10", "12.5"], "answer": 2, "hint": "In steady state the capacitor branch carries no current; only the forward-biased diode branch (4 Ω) conducts.", "solution": "I = 2.5/(1 + 4) = 0.5 A ⇒ V across the branches = 2 V ⇒ Q = 5 µF × 2 V = 10 µC.", "source": "JEE Main 2026 · 21 Jan · Shift 2"},
);
